<script>
import AsideVue from "@/components/AsideVue.vue";

import chat22232 from "@/assets/image/teacher/2223-2.png";
import chat22233 from "@/assets/image/teacher/2223-3.png";
import chat22234 from "@/assets/image/teacher/2223-4.png";
import chat24252 from "@/assets/image/teacher/2425-4.png";
import chat24254 from "@/assets/image/teacher/2425-4.png";
import {ArrowLeft, ArrowRight, Search, Warning} from "@element-plus/icons-vue";
import * as echarts from "echarts";
import axios from "axios";

// eslint-disable-next-line vue/no-export-in-script-setup
export default {
  name: "Test",
  components: {
    AsideVue,
  },
  data() {
    return {
      // 大章节
      // hasAnswerRate: 0
      // 已经答题人数de 变量
      master_rate: 0,
      activeUsers: 1024,
      average_score: 0,
      hasAnswer: 0,
      showTestButton: false,
      examList: [],
      user_answer: [],
      showScore: false,
      isTeacher: false,
      score: 0, // 测试得分
      chat2122: false, // 是否显示chat2122
      chat2223: false, // 是否显示chat2223
      chat2324: false, // 是否显示chat2224
      chat2425: false, // 是否显示chat2224
      // 展示重难点分析
      form: { //查询表单
        chapter: '',
        subchapter: '',
        grade: '',
      },
      chat22232: chat22232,
      chat22233: chat22233,
      chat22234: chat22234,
      chat24252: chat24252,
      chat24254: chat24254,
      showAnalysis: false,
      showAnswer: false,
      showTest: true,
      activeName: '1',
      selectedCategory: '',
      selectedItem: '',
      categories: [
        {value: '1', label: '第一章  数据结构概述'},
        {value: '2', label: '第二章  顺序表'},
        {value: '3', label: '第三章  栈和队列'},
        {value: '4', label: '第四章  串'},
        {value: '5', label: '第五章  树'},
        {value: '6', label: '第六章  图'},
        {value: '7', label: '第七章  查找'},
        {value: '8', label: '第八章  排序'},
      ],
      items: [],
      // === 答题防作弊相关 ===
      antiCheatEnabled: false,
      mediaStream: null,
      snapshotCanvas: null,
      snapshotTimer: null,
      snapshotCountdownTimer: null,
      nextSnapshotSeconds: 180,
      snapshotUploading: false,
      violationCount: 0,
    }
  },
  created() {
    //   判断是否是老师
    this.isTeacher = localStorage.getItem('username') === 'admin'
  },
  computed: {
    isCollapse() {
      return document.documentElement.clientWidth <= 1100;
    },
    //   监听 hasAnswerRate 改变时，重新计算hasAnswer 和 noAnswer
    noAnswer() {
      return 64 - this.hasAnswer
    },
    hasAnswerRate() {  // 测验完成率
      //   四舍五入保留 2位 小数点
      var rate = this.hasAnswer / 64 * 100
      return Math.round(rate * 100) / 100; // 输出：1.23
    },
    nextSnapshotCountdown() {
      const m = Math.floor(this.nextSnapshotSeconds / 60);
      const s = this.nextSnapshotSeconds % 60;
      return `${m}:${s.toString().padStart(2, '0')}`;
    },
    username() {
      return localStorage.getItem('username') || '';
    }
  },
  mounted() {
    window.onresize = () => {
      this.isCollapse = document.documentElement.clientWidth <= 1100;
    };
    this.get2122Chart1()
    this.get2223Chart1()
    this.get2324Chart1()
    this.get2425Chart1()
    // this.get2425Chart3()
    this.get2425Chart4()

    // this.get2223Chart2()
  },
  beforeUnmount() {
    this.stopAntiCheat();
  },
  methods: {
    // ============ 防作弊相关 ============
    async startAntiCheat() {
      if (this.isTeacher) return;  // 教师不需要防作弊
      if (this.antiCheatEnabled) return;

      // 申请摄像头权限
      try {
        this.mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { width: 640, height: 480 },
          audio: false
        });
      } catch (err) {
        console.error('摄像头权限获取失败:', err);
        this.$message.error('无法访问摄像头，答题监控无法启用。请允许摄像头权限后刷新页面。');
        return;
      }

      this.antiCheatEnabled = true;
      this.violationCount = 0;

      // 监听页面可见性（防止切屏）
      document.addEventListener('visibilitychange', this.handleVisibilityChange);
      // 监听窗口失焦（防止切到其他应用）
      window.addEventListener('blur', this.handleWindowBlur);
      // 监听鼠标离开窗口（防止查看其他资料）
      document.addEventListener('mouseleave', this.handleMouseLeave);
      // 禁用右键菜单
      document.addEventListener('contextmenu', this.disableContextMenu);
      // 禁用复制/粘贴/截屏相关快捷键
      document.addEventListener('keydown', this.handleKeydown);
      // 阻止原生拖拽
      document.addEventListener('dragstart', this.disableDrag);

      // 启动定时截图（每3分钟）
      this.startSnapshotSchedule();
      // 立即拍一张
      this.captureAndUploadSnapshot();

      this.$message.success('答题监控已启用，请勿离开页面或使用作弊插件。');
    },
    stopAntiCheat() {
      if (!this.antiCheatEnabled) return;
      this.antiCheatEnabled = false;

      if (this.snapshotTimer) {
        clearInterval(this.snapshotTimer);
        this.snapshotTimer = null;
      }
      if (this.snapshotCountdownTimer) {
        clearInterval(this.snapshotCountdownTimer);
        this.snapshotCountdownTimer = null;
      }

      document.removeEventListener('visibilitychange', this.handleVisibilityChange);
      window.removeEventListener('blur', this.handleWindowBlur);
      document.removeEventListener('mouseleave', this.handleMouseLeave);
      document.removeEventListener('contextmenu', this.disableContextMenu);
      document.removeEventListener('keydown', this.handleKeydown);
      document.removeEventListener('dragstart', this.disableDrag);

      if (this.mediaStream) {
        this.mediaStream.getTracks().forEach(track => track.stop());
        this.mediaStream = null;
      }
    },
    startSnapshotSchedule() {
      this.nextSnapshotSeconds = 180;
      if (this.snapshotCountdownTimer) clearInterval(this.snapshotCountdownTimer);
      this.snapshotCountdownTimer = setInterval(() => {
        if (this.nextSnapshotSeconds > 0) {
          this.nextSnapshotSeconds--;
        }
      }, 1000);

      if (this.snapshotTimer) clearInterval(this.snapshotTimer);
      this.snapshotTimer = setInterval(() => {
        this.captureAndUploadSnapshot();
        this.nextSnapshotSeconds = 180;
      }, 3 * 60 * 1000);
    },
    captureAndUploadSnapshot() {
      if (!this.mediaStream) return;
      try {
        const video = document.createElement('video');
        video.srcObject = this.mediaStream;
        video.play();
        video.addEventListener('loadeddata', () => {
          const canvas = document.createElement('canvas');
          canvas.width = 640;
          canvas.height = 480;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(video, 0, 0, 640, 480);
          canvas.toBlob((blob) => {
            if (blob) this.uploadSnapshot(blob);
          }, 'image/jpeg', 0.8);
        }, { once: true });
      } catch (err) {
        console.error('截图失败:', err);
      }
    },
    async uploadSnapshot(blob) {
      if (this.snapshotUploading) return;
      this.snapshotUploading = true;
      const formData = new FormData();
      formData.append('image', blob, 'snapshot.jpg');
      formData.append('username', this.username);
      formData.append('chapter', this.selectedCategory || '');
      formData.append('subchapter', this.selectedItem || '');
      try {
        await axios.post('/api/uploadExamSnapshot', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        console.log('答题截图已上传');
      } catch (err) {
        console.error('上传答题截图失败:', err);
      } finally {
        this.snapshotUploading = false;
      }
    },
    // === 事件检测处理器 ===
    reportExamViolation(eventType, eventDetail) {
      axios.post('/api/exam/behavior/event', {
        username: this.username,
        chapter: this.selectedCategory || '',
        subchapter: this.selectedItem || '',
        eventType,
        eventDetail
      }).catch(err => console.error('上报答题异常失败:', err));
    },
    handleVisibilityChange() {
      if (document.hidden && this.antiCheatEnabled) {
        this.violationCount++;
        this.reportExamViolation('page_hidden', '答题期间切换或隐藏了当前页面');
        this.$message.error(`检测到离开答题页面！违规次数：${this.violationCount}`);
      }
    },
    handleWindowBlur() {
      if (this.antiCheatEnabled) {
        this.violationCount++;
        this.reportExamViolation('window_blur', '答题窗口失去焦点，可能切换到其他应用');
        this.$message.warning(`检测到窗口失焦（可能切换应用）！违规次数：${this.violationCount}`);
      }
    },
    handleMouseLeave(e) {
      if (this.antiCheatEnabled && (e.clientY <= 0 || e.clientX <= 0 || e.clientX >= window.innerWidth || e.clientY >= window.innerHeight)) {
        this.violationCount++;
        this.reportExamViolation('mouse_leave', '鼠标离开答题页面可视区域');
        this.$message.warning(`检测到鼠标离开答题区域！违规次数：${this.violationCount}`);
      }
    },
    disableContextMenu(e) {
      if (this.antiCheatEnabled) {
        e.preventDefault();
        this.reportExamViolation('context_menu', '答题期间尝试打开右键菜单');
        this.$message.warning('答题期间禁止右键操作');
      }
    },
    disableDrag(e) {
      if (this.antiCheatEnabled) e.preventDefault();
    },
    handleKeydown(e) {
      if (!this.antiCheatEnabled) return;
      const key = e.key ? e.key.toLowerCase() : '';
      const ctrl = e.ctrlKey || e.metaKey;
      // 禁止截屏相关组合键（PrintScreen / Ctrl+P / Ctrl+S / Ctrl+C / Ctrl+V / Ctrl+X / F12 / Ctrl+Shift+I 等）
      if (key === 'printscreen') {
        this.violationCount++;
        this.reportExamViolation('screenshot_key', '检测到 PrintScreen 截屏按键');
        this.$message.error(`检测到截屏操作！违规次数：${this.violationCount}`);
        e.preventDefault();
        return;
      }
      if (ctrl && ['p', 's', 'c', 'v', 'x', 'a'].includes(key)) {
        this.reportExamViolation('forbidden_shortcut', `检测到受限快捷键 Ctrl/Cmd+${key.toUpperCase()}`);
        this.$message.warning('答题期间禁止复制/粘贴/打印/保存');
        e.preventDefault();
        return;
      }
      if (key === 'f12' || (ctrl && e.shiftKey && ['i', 'j', 'c'].includes(key))) {
        this.reportExamViolation('developer_tools', '检测到尝试打开开发者工具');
        this.$message.warning('答题期间禁止开发者工具');
        e.preventDefault();
        return;
      }
      // 检测浏览器插件打开的开发者面板（粗略检测：通过 window.chrome）
      if (!window.chrome && /chrome/i.test(navigator.userAgent)) {
        this.violationCount++;
      }
    },
    checkExtensions() {
      // 通过探测常用插件的资源来粗略判断是否有插件运行
      const testElements = [
        { name: 'Grammarly', id: '__GRAMMARLY_CSS__' },
      ];
      // 此方法仅为示意，浏览器插件检测在标准 Web API 下受限
      return false;
    },
    // ============ 业务方法 ============
    reTest() {
      this.showScore = false
      this.user_answer = []
      this.score = 0
    },
    submitTest() {
      // 获取用户答案 判断是否完成了答题
      if (this.user_answer.length !== this.examList.length) {
        this.$message({
          type: 'warning',
          message: '请先完成所有题目'
        })
        return
      }
      this.score = 0
      // 遍历 user_answer 和 examList 题目统计得分
      for (let i = 0; i < this.examList.length; i++) {
        //   遍历用户答案
        if (this.user_answer[i] === this.examList[i].correct_answer) {
          this.score += 2
        }
      }

      this.$message({
        type: 'success',
        message: '提交成功'
      })
      //  显示测验 得分
      this.showScore = true
      // 提交后停止答题监控
      this.stopAntiCheat()
      // 将答题记录 存放在数据库中
      axios.post('/api/examRecord', {
        username: localStorage.getItem('username'),
        chapter: this.selectedCategory,
        subchapter: this.selectedItem,
        score: this.score
      }).then(res => {
        console.log(res)

      })
    },
