    async analy() {
      //   分析几个学期的学生的课程重难点
      console.log(this.form.grade)
      // 判断表单是否为空？
      if (this.form.chapter === '') {
        this.$message.info('请选择要分析的章节！')
        return
      }
      if (this.selectedItem === '') {
        this.$message.info('请选择要分析的小节！')
        return
      }
      if (this.form.grade === '') {
        this.$message.info('请选择要分析的学期！')
        return
      }

      if (this.form.grade === '2021-2022') {
        this.$message.success('2021-2022学期学习重难点分析成功...')
        this.chat2122 = true
        this.chat2223 = false
        this.chat2324 = false

      } else if (this.form.grade === '2022-2023') {
        this.$message.success('2023-2024学期学习重难点分析成功...')
        this.chat2324 = false
        this.chat2223 = true
        this.chat2122 = false
      } else if (this.form.grade === '2023-2024') {
        this.$message.success('2023-2024学期学习重难点分析成功...')
        this.chat2324 = true
        this.chat2223 = false
        this.chat2122 = false
      } else if (this.form.grade === '2024-2025') {
        this.$message.success('2024-2025学期学习重难点分析成功...')
        this.chat2324 = false
        this.chat2223 = false
        this.chat2122 = false
        this.chat2425 = true
        //   查询已经答题
        //   categories 根据课程名查询
        //      categories: [
        //   {value: '1', label: '第一章  数据结构概述'},
        //   {value: '2', label: '第二章  顺序表'},
        //   {value: '3', label: '第三章  栈和队列'},
        //   {value: '4', label: '第四章  串'},
        //   {value: '5', label: '第五章  树'},
        //   {value: '6', label: '第六章  图'},
        //   {value: '7', label: '第七章  查找'},
        //   {value: '8', label: '第八章  排序'},
        // ],
        // 遍历categories  根据label查找对应的value
        this.categories.forEach(item => {
          if (item.label === this.form.chapter) {
            this.selectedCategory = item.value
          }
        })
        const data = {
          chapter: this.selectedCategory,
          subchapter: this.selectedItem
        };
        await axios.post('/api/examRecordCount', data)
            .then(response => {
              console.log("fanhui" + response.data)
              // examList 转为JSON数据
              this.hasAnswer = response.data
              // this.examList 的类型
              // 遍历examList  将examList的每一项 转为JSON数据  之后返回给examList
            })

        // this.hasAnswer 转为数字
        this.hasAnswer = parseFloat(this.hasAnswer)
        this.noAnswer = 64 - this.hasAnswer
        this.get2425Chart0()
        this.get2425Chart2()
        this.get2425Chart3()
        this.getAverageScore()
      }
    },
