      const adata = {
        username: localStorage.getItem('username'),
        chapter: this.selectedCategory,
        subchapter: this.selectedItem,
      };
      await axios.post('/api/hasExam', adata)
          .then(response => {
            console.log("fanhui" + response.data)
            // examList 转为JSON数据
            // alert(response.data === '')
            if (response.data !== '') { // 说明有答题记录
              this.showScore = true
              this.score = response.data[0].score  // 这里只会返回一个对象~
